# ============================================================
# Schwarzschild-AdS scalar spectral QNM solver
# Generalized coefficient boundary-condition version
#
# Maple exports matrices for the quadratic pencil
#
#     M0 + i*Omega*M1 + Omega^2*M2 = 0.
#
# This Julia code solves the corresponding generalized eigenvalue
# problem, identifies modes stable under the three spectral resolutions
# generated by the Maple assembler, and writes the same diagnostic data
# files as before. In addition, it keeps the search for unstable modes:
# with time dependence exp(-i omega t), unstable modes have Im(Omega) > 0.
#
#
# Default Maple output directory:
#
#     C:/Users/david/Documents/MAPLEFILESOLDPC/SPECTRAL DENYS/09-SAdS/data
#
# The file tag is detected automatically from the available Maple files.
# For generalized boundary-condition files generated by the Maple assembler,
# tags include a theta suffix such as th0, th1over4pi, or th1over2pi.
# You can override the full tag with SADS_FILETAG, or set SADS_THETA / SADS_THETA_TAG.
# ============================================================

# ------------------------------------------------------------
# Precision
# ------------------------------------------------------------

const FILE_DECIMAL_DIGITS = parse(Int, get(ENV, "SADS_FILE_DECIMAL_DIGITS", "200"))
const WORK_DECIMAL_DIGITS = parse(Int, get(ENV, "SADS_WORK_DECIMAL_DIGITS", "220"))

setprecision(BigFloat, WORK_DECIMAL_DIGITS; base = 10)

# ------------------------------------------------------------
# Number parsing and Maple-compatible xplus file tags
# ------------------------------------------------------------
# The physical input xplus = r_+/R may be supplied as
#
#     SADS_XPLUS = "50"
#     SADS_XPLUS = "0.1"
#     SADS_XPLUS = "0,1"      # decimal comma, interpreted as 0.1
#     SADS_XPLUS = "1/12"
#
# The corresponding Maple file tag is detected automatically. For example,
# "1/12" or "1over12" gives xp1over12_a83, while "0.1" or "0,1" gives xp100000_a100
# for the current sanitized Maple assembler convention.

normalize_decimal_string(s::AbstractString) = replace(strip(s), ',' => '.')

function parse_big_number(s::AbstractString)
    t = lowercase(normalize_decimal_string(s))

    if occursin("over", t)
        parts = split(t, "over")
        length(parts) == 2 || error("Invalid rational number: $s")
        num = parse_big_number(parts[1])
        den = parse_big_number(parts[2])
        iszero(den) && error("Invalid rational number with zero denominator: $s")
        return num / den
    elseif occursin('/', t)
        parts = split(t, '/')
        length(parts) == 2 || error("Invalid rational number: $s")
        num = parse_big_number(parts[1])
        den = parse_big_number(parts[2])
        iszero(den) && error("Invalid rational number with zero denominator: $s")
        return num / den
    else
        return parse(BigFloat, t)
    end
end

bf(s::AbstractString) = parse_big_number(s)

function integerish_tag_from_value(v::BigFloat)
    vf = Float64(v)
    if isfinite(vf) && abs(vf - round(vf)) < 100 * eps(Float64) * max(1.0, abs(vf))
        return string(Int(round(vf)))
    end
    return nothing
end

function rational_xplus_tag_from_input(s::AbstractString)
    t = lowercase(normalize_decimal_string(s))

    if occursin("over", t)
        parts = split(t, "over")
    elseif occursin('/', t)
        parts = split(t, '/')
    else
        return nothing
    end

    length(parts) == 2 || error("Invalid rational xplus input: $s")

    # These are file-name tags, so keep them simple. The usual use is integer
    # over integer, e.g. 1/12 -> 1over12. Decimal commas are already converted.
    numtag = replace(strip(parts[1]), '.' => "p")
    dentag = replace(strip(parts[2]), '.' => "p")
    isempty(numtag) && error("Invalid rational xplus numerator in: $s")
    isempty(dentag) && error("Invalid rational xplus denominator in: $s")
    return "$(numtag)over$(dentag)"
end

function decimal_micro_xplus_tag(v::BigFloat)
    # This matches the sanitized Maple convention for non-integer, non-rational
    # xplus values: xptag := round(1000000*evalf(xp)).
    return string(Int(round(Float64(1_000_000 * v))))
end

function simple_decimal_text_tag(s::AbstractString)
    # Kept as a fallback for older Maple files that used raw decimal text in
    # file names. Use p instead of . and avoid / entirely.
    t = normalize_decimal_string(s)
    t = replace(t, '/' => "over")
    t = replace(t, '.' => "p")
    return t
end

function xplus_tag_from_input(s::AbstractString)
    v = parse_big_number(s)

    inttag = integerish_tag_from_value(v)
    inttag !== nothing && return inttag

    rtag = rational_xplus_tag_from_input(s)
    rtag !== nothing && return rtag

    return decimal_micro_xplus_tag(v)
end

function atag_from_xplus_string(s::AbstractString)
    v = parse_big_number(s)
    return string(Int(round(Float64(1000 * v))))
end

function alternative_xplus_tags(s::AbstractString)
    v = parse_big_number(s)
    tags = String[]

    # Primary/default tag.
    push!(tags, xplus_tag_from_input(s))

    # If the user supplied a decimal, also try the raw-ish older text and a
    # simple rational approximation. This makes detection robust if Maple was
    # run with xp := 0.1, xp := .1, or xp := 1/10.
    push!(tags, decimal_micro_xplus_tag(v))
    push!(tags, simple_decimal_text_tag(s))

    vf = Float64(v)
    if isfinite(vf)
        r = rationalize(vf; tol = 1e-12)
        if denominator(r) != 1 && denominator(r) <= 10_000
            push!(tags, "$(numerator(r))over$(denominator(r))")
        elseif denominator(r) == 1
            push!(tags, string(numerator(r)))
        end
    end

    return unique(filter(!isempty, tags))
end


# ------------------------------------------------------------
# Generalized boundary-condition theta tags
# ------------------------------------------------------------
# The Maple assembler writes theta into the file tag as, for example,
#
#     th0
#     th1over8pi
#     th1over4pi
#     th3over8pi
#     th1over2pi
#
# This Julia script accepts the following inputs:
#
#     SADS_THETA = "0"
#     SADS_THETA = "pi/4"
#     SADS_THETA = "1/4"        # interpreted as pi/4 for Maple-tag purposes
#     SADS_THETA = "1over4"     # interpreted as pi/4 for Maple-tag purposes
#     SADS_THETA = "th1over4pi"
#
# You can always bypass automatic parsing by setting
#
#     SADS_THETA_TAG = "th1over4pi"
#
# or by setting the full
#
#     SADS_FILETAG = "s0_L3_xp50_a50000_th1over4pi".

function parse_rational_text(t::AbstractString)
    u = lowercase(normalize_decimal_string(t))
    u = replace(u, "π" => "pi")
    u = replace(u, "*" => "")
    u = strip(u)

    if occursin("over", u)
        parts = split(u, "over")
        length(parts) == 2 || error("Invalid rational text: $t")
        return parse(BigFloat, strip(parts[1])) / parse(BigFloat, strip(parts[2]))
    elseif occursin('/', u)
        parts = split(u, '/')
        length(parts) == 2 || error("Invalid rational text: $t")
        return parse(BigFloat, strip(parts[1])) / parse(BigFloat, strip(parts[2]))
    else
        return parse(BigFloat, u)
    end
end

function rational_pair_from_text(t::AbstractString)
    u = lowercase(normalize_decimal_string(t))
    u = replace(u, "π" => "pi")
    u = replace(u, "*" => "")
    u = strip(u)

    if occursin("over", u)
        parts = split(u, "over")
    elseif occursin('/', u)
        parts = split(u, '/')
    else
        return nothing
    end

    length(parts) == 2 || error("Invalid rational theta text: $t")
    num = strip(parts[1])
    den = strip(parts[2])
    isempty(num) && error("Empty numerator in theta text: $t")
    isempty(den) && error("Empty denominator in theta text: $t")
    return (num, den)
end

function theta_fraction_pair_from_input(s::AbstractString)
    t = lowercase(normalize_decimal_string(s))
    t = replace(t, "π" => "pi")
    t = replace(t, "*" => "")
    t = strip(t)

    if startswith(t, "th")
        tagbody = t[3:end]
        tagbody == "0" && return ("0", "1")
        endswith(tagbody, "pi") || return nothing
        frac = tagbody[1:end-2]
        if occursin("over", frac)
            parts = split(frac, "over")
            length(parts) == 2 || error("Invalid theta tag: $s")
            return (strip(parts[1]), strip(parts[2]))
        elseif isempty(frac)
            return ("1", "1")
        else
            return (strip(frac), "1")
        end
    end

    if t == "0" || t == "0.0" || t == "+0" || t == "+0.0"
        return ("0", "1")
    end

    # Inputs containing pi are interpreted literally as multiples of pi.
    if occursin("pi", t)
        if t == "pi"
            return ("1", "1")
        elseif startswith(t, "pi/")
            return ("1", strip(t[4:end]))
        elseif startswith(t, "pi") && length(t) > 2 && isdigit(t[3])
            # not a common form; fall through to numeric parsing below
        elseif endswith(t, "pi")
            coeff = strip(t[1:end-2])
            isempty(coeff) && return ("1", "1")
            pair = rational_pair_from_text(coeff)
            pair !== nothing && return pair
            return (coeff, "1")
        elseif occursin("pi/", t)
            parts = split(t, "pi/")
            length(parts) == 2 || error("Invalid theta input: $s")
            coeff = strip(parts[1])
            isempty(coeff) && (coeff = "1")
            return (coeff, strip(parts[2]))
        else
            # Fallback numerical parser below.
        end
    end

    # Inputs like 1/4 or 1over4 are interpreted as fractions of pi, because
    # this is how the Maple theta_list is written.
    pair = rational_pair_from_text(t)
    pair !== nothing && return pair

    # Decimal input is interpreted as radians. Try to recover a simple
    # rational multiple of pi for the tag.
    try
        theta_val = parse(BigFloat, t)
        frac = Float64(theta_val / BigFloat(pi))
        if isfinite(frac)
            r = rationalize(frac; tol = 1e-12)
            if denominator(r) <= 10_000
                return (string(numerator(r)), string(denominator(r)))
            end
        end
    catch
        # Leave as no rational pair.
    end

    return nothing
end

function theta_tag_from_input(s::AbstractString)
    t = lowercase(normalize_decimal_string(s))
    t = replace(t, "π" => "pi")
    t = replace(t, "*" => "")
    t = strip(t)

    startswith(t, "th") && return t

    pair = theta_fraction_pair_from_input(t)
    if pair !== nothing
        num, den = pair
        if parse(BigFloat, num) == 0
            return "th0"
        elseif den == "1"
            return "th$(num)pi"
        else
            return "th$(num)over$(den)pi"
        end
    end

    # Last-resort tag for a decimal radian value. Usually you should set
    # SADS_THETA_TAG manually if Maple did not use a rational multiple of pi.
    safe = replace(t, '.' => "p")
    safe = replace(safe, '-' => "m")
    safe = replace(safe, '+' => "")
    safe = replace(safe, '/' => "over")
    return "th$(safe)"
end

function parse_theta_value(s::AbstractString)
    t = lowercase(normalize_decimal_string(s))
    t = replace(t, "π" => "pi")
    t = replace(t, "*" => "")
    t = strip(t)

    if startswith(t, "th")
        pair = theta_fraction_pair_from_input(t)
        pair === nothing && error("Cannot parse theta tag as a value: $s")
        num, den = pair
        return BigFloat(pi) * parse(BigFloat, num) / parse(BigFloat, den)
    end

    if t == "0" || t == "0.0" || t == "+0" || t == "+0.0"
        return zero(BigFloat)
    end

    pair = theta_fraction_pair_from_input(t)
    if pair !== nothing
        num, den = pair
        return BigFloat(pi) * parse(BigFloat, num) / parse(BigFloat, den)
    end

    # Decimal without pi is interpreted as radians.
    return parse(BigFloat, t)
end

