const SPIN = parse(Int, get(ENV, "SADS_SPIN", "0"))
const ELL  = parse(Int, get(ENV, "SADS_ELL",  "3"))

# xplus = r_+/R. Horowitz-Hubeny values such as r_+ = 50 with R = 1
# correspond to XPLUS = 50 here.
const XPLUS_INPUT = get(ENV, "SADS_XPLUS", "50")
const XPLUS = parse_big_number(XPLUS_INPUT)

# These tags only affect file names. They should match how Maple wrote them.
const XPLUS_TAG = get(ENV, "SADS_XPLUS_TAG", xplus_tag_from_input(XPLUS_INPUT))
const ATAG_TAG  = get(ENV, "SADS_ATAG", atag_from_xplus_string(XPLUS_INPUT))

# Generalized coefficient boundary-condition angle.
# theta = 0 is Dirichlet; theta = pi/2 is coefficient-Neumann.
const THETA_INPUT = get(ENV, "SADS_THETA", "0")
const THETA = parse_theta_value(THETA_INPUT)
const THETA_TAG = get(ENV, "SADS_THETA_TAG", theta_tag_from_input(THETA_INPUT))

function validate_sector(s::Integer, ell::Integer)
    if s == 0
        ell >= 0 || error("For s=0 one needs ell >= 0.")
    elseif s == 1
        ell >= 1 || error("For s=1 one needs ell >= 1.")
    elseif s == 2
        ell >= 2 || error("For s=2 one needs ell >= 2.")
    else
        error("Unknown spin sector s=$s. Use s=0, 1, or 2.")
    end
    return nothing
end

validate_sector(SPIN, ELL)

const EPSILON = 1 - SPIN^2

function sector_name(s::Integer)
    if s == 0
        return "massless scalar"
    elseif s == 1
        return "electromagnetic"
    elseif s == 2
        return "gravitational"
    else
        return "unknown"
    end
end

