const DATA_DIR = get(ENV, "SADS_DATA_DIR",
    raw"C:\Users\david\Documents\MAPLEFILESOLDPC\SPECTRAL DENYS\09-SAdS\data")

function parse_n_vals(s::AbstractString)
    vals = [parse(Int, strip(x)) for x in split(s, ",") if !isempty(strip(x))]
    length(vals) == 3 || error("SADS_N_VALS must contain exactly three comma-separated integers, e.g. 90,95,100")
    return Tuple(vals)
end

const N_VALS = parse_n_vals(get(ENV, "SADS_N_VALS", "190,195,200"))

# ------------------------------------------------------------
# File-tag detection
# ------------------------------------------------------------

function default_filetag_candidates()
    base = "s$(SPIN)_L$(ELL)"
    tags = String[]

    # User override has priority.
    if haskey(ENV, "SADS_FILETAG")
        push!(tags, ENV["SADS_FILETAG"])
    end

    # New generalized-boundary-condition Maple assembler tags include a
    # theta suffix, e.g. s0_L3_xp50_a50000_th1over4pi.
    for xtag in alternative_xplus_tags(XPLUS_INPUT)
        core = "$(base)_xp$(xtag)_a$(ATAG_TAG)"
        push!(tags, "$(core)_$(THETA_TAG)")

        # Backward compatibility for old Dirichlet files without theta suffix.
        if THETA_TAG == "th0"
            push!(tags, core)
        end

        # Common alternatives, kept robust against harmless changes in the
        # order of the Maple cat(...) arguments.
        push!(tags, "$(base)_a$(ATAG_TAG)_xp$(xtag)_$(THETA_TAG)")
        push!(tags, "$(base)_xp$(xtag)_$(THETA_TAG)")
        push!(tags, "$(base)_a$(ATAG_TAG)_$(THETA_TAG)")

        if THETA_TAG == "th0"
            push!(tags, "$(base)_a$(ATAG_TAG)_xp$(xtag)")
            push!(tags, "$(base)_a$(xtag)")
            push!(tags, "$(base)_xp$(xtag)")
        end

        # If Maple printed a floating integer as 50. or 50.0, these cover it.
        if occursin(r"^[0-9]+$", xtag)
            push!(tags, "$(base)_xp$(xtag)._a$(ATAG_TAG)_$(THETA_TAG)")
            push!(tags, "$(base)_xp$(xtag).0_a$(ATAG_TAG)_$(THETA_TAG)")
            if THETA_TAG == "th0"
                push!(tags, "$(base)_xp$(xtag)._a$(ATAG_TAG)")
                push!(tags, "$(base)_xp$(xtag).0_a$(ATAG_TAG)")
            end
        end
    end

    return unique(tags)
end

matfile_with_tag(prefix::AbstractString, n::Integer, tag::AbstractString) =
    joinpath(DATA_DIR, "$(prefix)-$(n)-$(tag).mat")

function matrix_files_exist_for_tag(tag::AbstractString)
    for n in N_VALS
        for prefix in ("M0", "M1", "M2")
            isfile(matfile_with_tag(prefix, n, tag)) || return false
        end
    end
    return true
end

function scan_filetags_from_directory()
    isdir(DATA_DIR) || return String[]

    n0 = N_VALS[1]
    pattern = Regex("^M0-$(n0)-(.+)\\.mat\$")
    base = "s$(SPIN)_L$(ELL)"
    tags = String[]

    for fname in readdir(DATA_DIR)
        m = match(pattern, fname)
        m === nothing && continue
        tag = m.captures[1]
        occursin(base, tag) || continue
        matrix_files_exist_for_tag(tag) || continue
        push!(tags, tag)
    end

    return sort(unique(tags))
end

function theta_tag_score(tag::AbstractString)
    # Lower scores are better. For theta=0, old files without a theta suffix
    # are allowed as a backward-compatible fallback. For theta != 0, require
    # the requested theta suffix unless SADS_FILETAG is set explicitly.
    occursin("_$(THETA_TAG)", tag) && return 0

    if THETA_TAG == "th0" && !occursin(r"_th[^_]+", tag)
        return 1
    end

    return 100
end

function requested_tag_score(tag::AbstractString)
    # Lower scores are better. A high score means that the tag does not look
    # compatible with the requested xplus/theta. This avoids accidentally
    # selecting a different run if DATA_DIR contains many datasets.
    tscore = theta_tag_score(tag)
    tscore >= 100 && return 100

    xtags = alternative_xplus_tags(XPLUS_INPUT)

    for xtag in xtags
        if occursin("_xp$(xtag)_a$(ATAG_TAG)", tag)
            return 10 * tscore + 0
        end
    end

    for xtag in xtags
        if occursin("_xp$(xtag)", tag) && occursin("_a$(ATAG_TAG)", tag)
            return 10 * tscore + 1
        end
    end

    if occursin("_a$(ATAG_TAG)", tag)
        return 10 * tscore + 2
    end

    for xtag in xtags
        if occursin("_xp$(xtag)", tag)
            return 10 * tscore + 3
        end
    end

    return 100
end

function scanned_filetags_compatible_with_request()
    scanned = scan_filetags_from_directory()
    scored = [(requested_tag_score(tag), tag) for tag in scanned]
    compatible = [(score, tag) for (score, tag) in scored if score < 100]
    sort!(compatible, by = x -> (x[1], x[2]))
    return [tag for (score, tag) in compatible]
end

function detect_filetag()
    if haskey(ENV, "SADS_FILETAG")
        tag = ENV["SADS_FILETAG"]
        matrix_files_exist_for_tag(tag) || error(
            "SADS_FILETAG=$tag was supplied, but the required M0/M1/M2 files were not found in DATA_DIR=$DATA_DIR"
        )
        return tag
    end

    for tag in default_filetag_candidates()
        if matrix_files_exist_for_tag(tag)
            return tag
        end
    end

    scanned = scanned_filetags_compatible_with_request()
    if !isempty(scanned)
        return first(scanned)
    end

    msg = IOBuffer()
    println(msg, "Could not detect a complete Maple file tag for the requested xplus.")
    println(msg, "DATA_DIR = ", DATA_DIR)
    println(msg, "Requested SADS_XPLUS = ", XPLUS_INPUT)
    println(msg, "Requested SADS_THETA = ", THETA_INPUT, "  (tag: ", THETA_TAG, ")")
    println(msg, "Parsed xplus = ", XPLUS)
    println(msg, "Inferred xplus tag = ", XPLUS_TAG)
    println(msg, "Inferred a/atag = ", ATAG_TAG)
    println(msg, "Tried these tags:")
    for tag in default_filetag_candidates()
        println(msg, "  ", tag)
    end
    println(msg, "Expected files of the form:")
    println(msg, "  M0-$(N_VALS[1])-<tag>.mat")
    println(msg, "  M1-$(N_VALS[1])-<tag>.mat")
    println(msg, "  M2-$(N_VALS[1])-<tag>.mat")
    if isdir(DATA_DIR)
        println(msg, "Files currently visible in DATA_DIR:")
        visible_files = sort(readdir(DATA_DIR))
        for fname in Iterators.take(visible_files, 40)
            println(msg, "  ", fname)
        end
    else
        println(msg, "DATA_DIR does not exist.")
    end
    error(String(take!(msg)))
end

const FILETAG = detect_filetag()

const OUT_DIR = get(ENV, "SADS_OUT_DIR", joinpath(DATA_DIR, "Julia", FILETAG))
mkpath(OUT_DIR)

matfile(prefix::AbstractString, n::Integer) = matfile_with_tag(prefix, n, FILETAG)
outfile(name::AbstractString) = joinpath(OUT_DIR, name)

