const DISPLAY_ZERO_TOL = bf(get(ENV, "SADS_DISPLAY_ZERO_TOL", "1e-20"))
const PLOT_ZERO_TOL    = bf(get(ENV, "SADS_PLOT_ZERO_TOL",    "1e-12"))

# Stable-mode matching tolerance between the three N runs.
const STABLE_RELTOL = bf(get(ENV, "SADS_STABLE_RELTOL", "1e-4"))
const STABLE_ABSTOL = bf(get(ENV, "SADS_STABLE_ABSTOL", "1e-4"))

# The generalized eigenproblem may contain a static Omega = 0 solution.
# This is normally not counted as a QNM.
const DISCARD_ZERO_MODE = lowercase(get(ENV, "SADS_DISCARD_ZERO_MODE", "true")) == "true"
const ZERO_MODE_TOL = bf(get(ENV, "SADS_ZERO_MODE_TOL", "1e-30"))

# With exp(-i omega t):
#   Im(Omega) < 0  damped/stable in time,
#   Im(Omega) > 0  unstable in time.
# We deliberately do not discard unstable modes from the candidate set.
const SEARCH_UNSTABLE_MODES = lowercase(get(ENV, "SADS_SEARCH_UNSTABLE", "true")) == "true"
const DAMPING_TOL = bf(get(ENV, "SADS_DAMPING_TOL", "1e-18"))

# Keep only one representative branch of the +/- Re(Omega) symmetry.
const KEEP_REPRESENTATIVE_BRANCH = lowercase(get(ENV, "SADS_KEEP_REPRESENTATIVE_BRANCH", "false")) == "true"
const REPRESENTATIVE_RE_TOL = bf(get(ENV, "SADS_REPRESENTATIVE_RE_TOL", "1e-10"))

# Threshold used only to split modes into oscillatory and purely imaginary lists.
const PURE_IMAG_RE_TOL = bf(get(ENV, "SADS_PURE_IMAG_RE_TOL", "1e-10"))

# Plot settings.
const USE_PLOTLYJS = lowercase(get(ENV, "SADS_USE_PLOTLYJS", "true")) == "true"
const SAVE_HTML_PLOTS = lowercase(get(ENV, "SADS_SAVE_HTML_PLOTS", "true")) == "true"

# ------------------------------------------------------------
# Matrix I/O and quadratic eigenvalue problem
# ------------------------------------------------------------

function read_big_matrix(path::AbstractString)
    isfile(path) || error("Missing input file: $path")

    A = readdlm(path, BigFloat)
    A = Matrix{BigFloat}(A)

    size(A, 1) == size(A, 2) ||
        error("Matrix is not square: $path has size $(size(A))")

    return A
end

# The generalized-boundary-condition Maple assembler uses the last row
# for the AdS-boundary condition. That row is independent of Omega, so the
# last rows of M1 and M2 are zero. Consequently the leading quadratic matrix
# M2 is singular. A generalized QZ algorithm can handle this, but Julia does
# not provide a BigFloat generalized eigensolver for a pair (A,B). We therefore
# eliminate the boundary constraint before linearizing the quadratic pencil.
#
# In detail, if the last row is c^T b = 0, we write b = Z u, where the columns
# of Z form an explicit basis of the nullspace of c^T. We then use only the
# first n-1 differential-equation rows and solve the reduced square QEP.
# This preserves the boundary condition exactly and removes the singular
# boundary row from the leading coefficient.

const REDUCE_BOUNDARY_ROW = lowercase(get(ENV, "SADS_REDUCE_BOUNDARY_ROW", "auto"))
const BOUNDARY_ROW_TOL = bf(get(ENV, "SADS_BOUNDARY_ROW_TOL", "1e-80"))

function row_maxabs(A::AbstractMatrix, i::Integer)
    m = BigFloat(0)
    for j in axes(A, 2)
        av = BigFloat(abs(A[i, j]))
        av > m && (m = av)
    end
    return m
end

function has_boundary_row(M0::AbstractMatrix{T}, M1::AbstractMatrix{T}, M2::AbstractMatrix{T}) where {T<:Real}
    n = size(M0, 1)
    m0 = row_maxabs(M0, n)
    m1 = row_maxabs(M1, n)
    m2 = row_maxabs(M2, n)
    return (m0 > BOUNDARY_ROW_TOL) && (m1 <= BOUNDARY_ROW_TOL) && (m2 <= BOUNDARY_ROW_TOL)
end

function should_reduce_boundary_row(M0, M1, M2)
    if REDUCE_BOUNDARY_ROW in ("true", "yes", "1")
        return true
    elseif REDUCE_BOUNDARY_ROW in ("false", "no", "0")
        return false
    elseif REDUCE_BOUNDARY_ROW == "auto"
        return has_boundary_row(M0, M1, M2)
    else
        error("Invalid SADS_REDUCE_BOUNDARY_ROW=$(REDUCE_BOUNDARY_ROW). Use auto, true, or false.")
    end
end

function nullspace_reduced_pencil(M0::AbstractMatrix{T},
                                  M1::AbstractMatrix{T},
                                  M2::AbstractMatrix{T}) where {T<:Real}
    n = size(M0, 1)
    n >= 2 || error("Cannot reduce a pencil of size n=$n")

    c = [BigFloat(M0[n, j]) for j in 1:n]
    pidx = argmax(abs.(c))
    cp = c[pidx]
    abs(cp) > BOUNDARY_ROW_TOL || error("Boundary row has no usable pivot; max |c_j|=$(abs(cp))")

    free = [j for j in 1:n if j != pidx]
    Zbasis = zeros(T, n, n - 1)

    for (col, j) in enumerate(free)
        Zbasis[j, col] = one(T)
        Zbasis[pidx, col] = T(-c[j] / cp)
    end

    rows = 1:(n - 1)
    R0 = Matrix(M0[rows, :]) * Zbasis
    R1 = Matrix(M1[rows, :]) * Zbasis
    R2 = Matrix(M2[rows, :]) * Zbasis

    return R0, R1, R2, pidx
end

function solve_linearized_pencil(A::AbstractMatrix{Complex{T}},
                                 B::AbstractMatrix{Complex{T}}) where {T<:Real}
    # Preferred path: after reducing the boundary row, B is normally
    # nonsingular. Then B \ A is an ordinary BigFloat matrix and GenericSchur
    # can compute its eigenvalues.
    try
        C = B \ A
        return Complex{T}.(eigvals(C))
    catch err
        @warn "BigFloat solve of the linearized pencil failed; falling back to ComplexF64 generalized QZ" exception=(err, catch_backtrace())
        vals64 = eigvals(ComplexF64.(A), ComplexF64.(B))
        return Complex{T}.(vals64)
    end
end

function qep_eigs(M0::AbstractMatrix{T},
                  M1::AbstractMatrix{T},
                  M2::AbstractMatrix{T}) where {T<:Real}

    n0 = size(M0, 1)

    @assert size(M0, 2) == n0 "M0 must be square"
    @assert size(M1) == (n0, n0) "M1 must match size(M0)"
    @assert size(M2) == (n0, n0) "M2 must match size(M0)"

    if should_reduce_boundary_row(M0, M1, M2)
        M0r, M1r, M2r, pidx = nullspace_reduced_pencil(M0, M1, M2)
        @info "Reduced boundary row before QEP linearization" original_size=n0 reduced_size=size(M0r,1) pivot_coefficient_index=pidx
        M0 = M0r
        M1 = M1r
        M2 = M2r
    end

    n = size(M0, 1)
    Tc = Complex{T}

    Z = zeros(Tc, n, n)
    I_n = Matrix{Tc}(I, n, n)

    M0c = Tc.(M0)
    M1c = Tc.(M1)
    M2c = Tc.(M2)

    # gamma = i gives M0 + i*Omega*M1 + Omega^2*M2 = 0.
    gamma = complex(zero(T), one(T))

    # Linearization A v = Omega B v with v = [b; Omega*b].
    A = [Z      I_n;
        -M0c   -gamma*M1c]

    B = [I_n   Z;
         Z     M2c]

    vals = solve_linearized_pencil(A, B)
    return Tc.(vals)
end

function finite_modes(vals)
    return [Omega for Omega in vals if isfinite(real(Omega)) && isfinite(imag(Omega))]
end

function is_candidate_mode(Omega)
    isfinite(real(Omega)) && isfinite(imag(Omega)) || return false

    if DISCARD_ZERO_MODE && abs(Omega) < ZERO_MODE_TOL
        return false
    end

    if KEEP_REPRESENTATIVE_BRANCH && real(Omega) < -REPRESENTATIVE_RE_TOL
        return false
    end

    if !SEARCH_UNSTABLE_MODES && imag(Omega) > DAMPING_TOL
        return false
    end

    return true
end

function candidate_modes(vals)
    return [Omega for Omega in vals if is_candidate_mode(Omega)]
end

function is_damped_mode(Omega)
    return imag(Omega) < -DAMPING_TOL
end

function is_unstable_mode(Omega)
    return imag(Omega) > DAMPING_TOL
end

function is_neutral_mode(Omega)
    return abs(imag(Omega)) <= DAMPING_TOL
end

function load_and_solve(n::Integer)
    M0 = read_big_matrix(matfile("M0", n))
    M1 = read_big_matrix(matfile("M1", n))
    M2 = read_big_matrix(matfile("M2", n))

    vals = qep_eigs(M0, M1, M2)
    vals_finite = finite_modes(vals)
    vals_candidate = candidate_modes(vals_finite)

    if length(vals_finite) != length(vals)
        @warn "Discarded non-finite eigenvalues" n=n total=length(vals) finite=length(vals_finite)
    end

    if length(vals_candidate) != length(vals_finite)
        @info "Applied nonphysical/candidate filters" n=n finite=length(vals_finite) candidates=length(vals_candidate)
    end

    return vals_finite, vals_candidate
end

# ------------------------------------------------------------
# Stable-mode identification across resolutions
# ------------------------------------------------------------

function nearest_mode(Omega, vals, used::AbstractVector{Bool})
    jmin = 0
    dmin = BigFloat(Inf)

    for j in eachindex(vals)
        used[j] && continue
        d = abs(vals[j] - Omega)
        if d < dmin
            dmin = d
            jmin = j
        end
    end

    return jmin, dmin
end

function nearest_mode_unrestricted(Omega, vals)
    jmin = 0
    dmin = BigFloat(Inf)

    for j in eachindex(vals)
        d = abs(vals[j] - Omega)
        if d < dmin
            dmin = d
            jmin = j
        end
    end

    return jmin, dmin
end

function sort_mode_indices(vals)
    return sortperm(
        1:length(vals),
        by = k -> (abs(imag(vals[k])), real(vals[k]))
    )
end

function sort_modes(vals)
    isempty(vals) && return vals
    return vals[sort_mode_indices(vals)]
end

function stable_modes(e1, e2, e3; reltol = STABLE_RELTOL, abstol = STABLE_ABSTOL)
    stable = Complex{BigFloat}[]

    e1m = Complex{BigFloat}[]
    e2m = Complex{BigFloat}[]
    e3m = Complex{BigFloat}[]

    err12 = BigFloat[]
    err23 = BigFloat[]
    err13 = BigFloat[]

    used2 = falses(length(e2))
    used3 = falses(length(e3))

    for Omega1 in e1
        j2, d12 = nearest_mode(Omega1, e2, used2)
        j2 == 0 && continue

        Omega2 = e2[j2]

        j3, d23 = nearest_mode(Omega2, e3, used3)
        j3 == 0 && continue

        Omega3 = e3[j3]
        d13 = abs(Omega1 - Omega3)

        scale = max(BigFloat(1), abs(Omega1), abs(Omega2), abs(Omega3))
        tol = max(abstol, reltol * scale)

        if max(d12, d23, d13) > tol
            continue
        end

        Omega_avg = (Omega1 + Omega2 + Omega3) / 3

        push!(stable, Omega_avg)
        push!(e1m, Omega1)
        push!(e2m, Omega2)
        push!(e3m, Omega3)

        push!(err12, d12)
        push!(err23, d23)
        push!(err13, d13)

        used2[j2] = true
        used3[j3] = true
    end

    p = sort_mode_indices(stable)

    return stable[p], e1m[p], e2m[p], e3m[p], err12[p], err23[p], err13[p]
end

function split_stable_modes(stable)
    pure_imag = Complex{BigFloat}[]
    oscillatory = Complex{BigFloat}[]

    for Omega in stable
        if abs(real(Omega)) < PURE_IMAG_RE_TOL
            push!(pure_imag, Omega)
        else
            push!(oscillatory, Omega)
        end
    end

    return sort_modes(oscillatory), sort_modes(pure_imag)
end

function split_by_time_behavior(vals)
    damped = Complex{BigFloat}[]
    unstable = Complex{BigFloat}[]
    neutral = Complex{BigFloat}[]

    for Omega in vals
        if is_damped_mode(Omega)
            push!(damped, Omega)
        elseif is_unstable_mode(Omega)
            push!(unstable, Omega)
        else
            push!(neutral, Omega)
        end
    end

    return sort_modes(damped), sort_modes(unstable), sort_modes(neutral)
end

# ------------------------------------------------------------
# File output
